mapper.select:
SELECT ifnull(sum(ifnull( (CASE OFFSET_FLAG WHEN #{OFFSET_FLAG_ZC} THEN -1 WHEN #{OFFSET_FLAG_CX} THEN 1 END ), 0)*AMOUNT),0) from ETR_CASH_POSITION_FLOW etpf where OFFSET_ID = #{entrustId}
and PORTFOLIO_ID = #{portfolioId}
AND ((OFFSET_FLAG = #{OFFSET_FLAG_ZC} and OFFSET_ID = ORDER_ID) or OFFSET_FLAG = #{OFFSET_FLAG_CX})

SELECT
100 - ifnull(sum(fcp.PRIN_AMT), 0)
FROM
FIN_CASH_PLAN fcp
inner join FIN_CASH_INFO fci
on fcp.CASH_ID = fci.CASH_ID
WHERE
fcp.FINPROD_ID = #{finprodId}

AND fcp.MDATE < #{settleDate}
and fci.CASH_TYPE_1 = #{cashType1}

select ifnull(sum(PLEDGE_NUMBER),0) from FIN_DEAL_PLEDGE where FINPROD_ID in (
    select TRADE_ID from TRD_PRODUCT_DEAL where TRADE_STATUS = '01' and (IS_CANCEL = 'N' or IS_CANCEL is null)
                                            and TRADE_ID in (select TRADE_ID from TRD_PRODUCT_DEAL_ADD where ENTRUST_ID = #{entrustId})
) and PLEDGE_FINPROD_ID=#{finprodId}
